use super::*;
use serde_json::{json,Value};
use kfc_kfc_alpha::kfc::xpxml::writer::r#impl::{MemoryXmlWriter::MemoryXmlWriter,BufferXmlWriter::BufferXmlWriter};
use crate::cn::wps::moss::{app::{KmoBookApi::KmoBookApi,KmoBooks::KmoBooks},filefmt::biff8::record::common::FormatRun::FormatRun};
use std::{cell::RefCell,rc::Rc as LocalRc,io::Write};
#[derive(Clone)]struct Bytes(LocalRc<RefCell<Vec<u8>>>);impl Write for Bytes{fn write(&mut self,b:&[u8])->std::io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn units(hex:&str)->Vec<u16>{(0..hex.len()).step_by(4).map(|i|u16::from_str_radix(&hex[i..i+4],16).unwrap()).collect()}
fn rich(input:&Value)->UnicodeString{let mut value=UnicodeString::new(input["text"].as_str().unwrap().into());let runs:Vec<_>=input["runs"].as_array().unwrap().iter().map(|r|FormatRun::new(r[0].as_i64().unwrap()as i16,r[1].as_i64().unwrap()as i16)).collect();if !runs.is_empty(){value.resetFormatRuns(runs);}value}
fn output(mut f:impl FnMut(&mut dyn XmlWriter))->Value{let mut m=MemoryXmlWriter::new();f(&mut m);let units=m.getCodeUnits().iter().map(|v|format!("{v:04x}")).collect::<String>();let bytes=Bytes(LocalRc::new(RefCell::new(vec![])));let mut b=BufferXmlWriter::new(Box::new(bytes.clone()));f(&mut b);b.flush();json!({"memoryResult":"ok","units":units,"bufferResult":"ok","bytes":base64(&bytes.0.borrow())})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]
fn original_android_sst_rich_runs_utf16_and_output_streams(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/sst-r0b35");let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();crate::cn::wps::moss::app::KmoLocale::KmoLocale::setLocale(j["locale"].as_str().unwrap().into());let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();for i in 0..8{book.getXFManager().borrow().createFont(&KmoBooks::createFontRecord(&format!("font{i}")));}let label=SstLabel::SstLabel(book.clone());let mut items=vec![];for source in input["items"].as_array().unwrap(){let value=rich(source);let fonts:Vec<_>=[i32::MIN,-1,0,1,2,3,4,5,10,32767,i32::MAX].into_iter().map(|i|label.getFontAtIndex(i,&value)).collect();items.push(json!({"input":source,"fonts":fonts,"output":output(|w|label.writeSharedItem(w,&value))}));}let texts:Vec<_>=input["texts"].as_array().unwrap().iter().map(|source|json!({"input":source,"output":output(|w|label.writerText(w,&units(source.as_str().unwrap())))})).collect();let sequences:Vec<_>=input["sequences"].as_array().unwrap().iter().map(|source|output(|w|{w.startElement("x");for(n,s)in source.as_array().unwrap().iter().enumerate(){w.addTextUtf16(&units(s.as_str().unwrap()));if n%2==0{w.flush();}}w.endElement("x");})).collect();let push=output(|w|{w.startElement("x");let mut m=MemoryXmlWriter::new();m.addTextUtf16(&[0xd83d]);w.pushWriter(Box::new(m));w.addTextUtf16(&[0xde00]);w.endElement("x");});book.getCellValueStore().borrow_mut().addUnicodeString(Some(Rc::new(rich(&input["items"][1]))));let full=output(|w|{w.startDocument();w.startElement("sst");label.write(w);w.endElement("sst");w.endDocument();});let actual=json!({"locale":crate::cn::wps::moss::app::KmoLocale::KmoLocale::getDefault(),"items":items,"texts":texts,"sequences":sequences,"push":push,"full":full});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&j,"root");}
